CREATE TABLE tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'active',used_bytes INTEGER NOT NULL DEFAULT 0 CHECK(used_bytes>=0),quota_bytes INTEGER NOT NULL DEFAULT 50000000000,paid_until INTEGER NOT NULL DEFAULT 0,cost_cents INTEGER,quote_cents INTEGER,billing_reference TEXT NOT NULL DEFAULT '',sale_allowed INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE tenant_members(tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(tenant_id,email));
CREATE INDEX tenant_members_email ON tenant_members(email);
CREATE TABLE admin_events(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,tenant_id TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
INSERT INTO tenants(id,name,owner_id,created_at) SELECT id,'My audit workspace',id,created_at FROM users;
INSERT INTO tenant_members SELECT id,email,'owner' FROM users;
ALTER TABLE audit_cases ADD COLUMN tenant_id TEXT REFERENCES tenants(id);
UPDATE audit_cases SET tenant_id=owner_id;
ALTER TABLE uploads ADD COLUMN tenant_id TEXT REFERENCES tenants(id);
UPDATE uploads SET tenant_id=user_id;
DELETE FROM case_members;
UPDATE tenants SET used_bytes=COALESCE((SELECT SUM(length(CAST(payload AS BLOB))) FROM audit_cases WHERE tenant_id=tenants.id),0)+COALESCE((SELECT SUM(size) FROM uploads WHERE tenant_id=tenants.id),0);
CREATE INDEX audit_cases_tenant ON audit_cases(tenant_id,id);
CREATE INDEX uploads_tenant ON uploads(tenant_id,id);
CREATE TRIGGER case_insert_quota BEFORE INSERT ON audit_cases BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER case_update_quota BEFORE UPDATE OF payload ON audit_cases WHEN length(CAST(NEW.payload AS BLOB))>length(CAST(OLD.payload AS BLOB)) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB))<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER case_insert_usage AFTER INSERT ON audit_cases BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER case_update_usage AFTER UPDATE OF payload ON audit_cases BEGIN UPDATE tenants SET used_bytes=used_bytes+length(CAST(NEW.payload AS BLOB))-length(CAST(OLD.payload AS BLOB)) WHERE id=NEW.tenant_id; END;
CREATE TRIGGER case_delete_usage AFTER DELETE ON audit_cases BEGIN UPDATE tenants SET used_bytes=used_bytes-length(CAST(OLD.payload AS BLOB)) WHERE id=OLD.tenant_id; END;
CREATE TRIGGER upload_insert_quota BEFORE INSERT ON uploads BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND status='active' AND used_bytes+NEW.size<=CASE WHEN paid_until>unixepoch() THEN quota_bytes ELSE 50000000000 END) THEN RAISE(ABORT,'Storage subscription required') END; END;
CREATE TRIGGER upload_insert_usage AFTER INSERT ON uploads BEGIN UPDATE tenants SET used_bytes=used_bytes+NEW.size WHERE id=NEW.tenant_id; END;
CREATE TRIGGER upload_delete_usage AFTER DELETE ON uploads BEGIN UPDATE tenants SET used_bytes=used_bytes-OLD.size WHERE id=OLD.tenant_id; END;
